const express = require('express');
const { SNSClient, PublishCommand } = require('@aws-sdk/client-sns');
const { MedicalRecordsDb } = require('../models/medical');

const app = express();
app.use(express.json());

const snsClient = new SNSClient({ region: process.env.AWS_REGION || 'us-east-1' });
const LAB_RESULTS_TOPIC_ARN = process.env.SNS_LAB_RESULTS_TOPIC_ARN;

app.post('/api/telehealth/broadcast-report', async (req, res) => {
  if (!req.user || !req.user.providerId) {
    return res.status(401).json({ error: 'Clinician authentication required' });
  }

  const { patientId, testCategory, diagnosticFindings, urgencyLevel } = req.body;

  if (!patientId || !diagnosticFindings) {
    return res.status(400).json({ error: 'patientId and diagnosticFindings are required' });
  }

  // Verify that the authenticated healthcare provider has an active care relationship with the patient
  const assignment = await MedicalRecordsDb.providerAssignments.findOne({
    where: {
      providerId: req.user.providerId,
      patientId: patientId,
      active: true
    }
  });

  if (!assignment) {
    return res.status(403).json({ error: 'Access denied: provider not assigned to this patient' });
  }

  const publishCmd = new PublishCommand({
    TopicArn: LAB_RESULTS_TOPIC_ARN,
    Subject: `Lab Report Ready: ${testCategory}`,
    Message: JSON.stringify({
      patientId,
      findings: diagnosticFindings,
      verifiedByProviderId: req.user.providerId,
      publishedAt: new Date().toISOString()
    }),
    MessageAttributes: {
      PatientId: {
        DataType: 'String',
        StringValue: patientId
      },
      Urgency: {
        DataType: 'String',
        StringValue: urgencyLevel || 'STANDARD'
      }
    }
  });

  try {
    const result = await snsClient.send(publishCmd);
    res.json({ success: true, messageId: result.MessageId });
  } catch (error) {
    res.status(500).json({ error: 'Failed to publish lab alert' });
  }
});

app.listen(3001);
